import zipfile, re
from xml.etree import ElementTree as ET
z=zipfile.ZipFile('/tmp/tiny.xlsx')
# workbook sheets
wb=ET.fromstring(z.read('xl/workbook.xml'))
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main','r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
sheets=[]
for s in wb.findall('.//m:sheets/m:sheet', ns):
    sheets.append((s.attrib.get('name'), s.attrib.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))
print('SHEETS', sheets)
rels=ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
rid_to_target={}
for rel in rels:
    rid_to_target[rel.attrib['Id']]=rel.attrib['Target']
# shared strings
ss=[]
if 'xl/sharedStrings.xml' in z.namelist():
    root=ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in root.findall('m:si', ns):
        texts=[t.text or '' for t in si.findall('.//m:t', ns)]
        ss.append(''.join(texts))
print('sharedStrings', len(ss))
for name, rid in sheets:
    target='xl/'+rid_to_target[rid].lstrip('/')
    if target.startswith('xl/xl/'):
        target=target[3:]
    root=ET.fromstring(z.read(target))
    rows=root.findall('m:sheetData/m:row', ns)
    nonempty=0
    sample=[]
    for row in rows:
        vals=[]
        for c in row.findall('m:c', ns):
            t=c.attrib.get('t')
            v=c.find('m:v', ns)
            if v is None or v.text is None:
                vals.append('')
                continue
            if t=='s':
                vals.append(ss[int(v.text)])
            else:
                vals.append(v.text)
        if any(x.strip() for x in vals if isinstance(x,str)):
            nonempty += 1
            if len(sample)<3:
                sample.append(vals[:8])
    print(f'{name}: rows_with_data={nonempty} sample={sample}')
