with zipfile.ZipFile(xlsx) as z:
    sst=[]
    if 'xl/sharedStrings.xml' in z.namelist():
        root=ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', ns):
            texts=[t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')]
            sst.append(''.join(texts))
    rels=ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rid_to={rel.attrib['Id']:rel.attrib['Target'] for rel in rels}
    wb=ET.fromstring(z.read('xl/workbook.xml'))
    print('\n=== Sheet tabs headers + SKU-like columns ===')
    for s in wb.findall('m:sheets/m:sheet', ns):
        name=s.attrib['name']
        rid=s.attrib['{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id']
        path='xl/'+rid_to[rid]
        root=ET.fromstring(z.read(path))
        rows=root.findall('m:sheetData/m:row', ns)
        if not rows: continue
        headers=[]
        for c in rows[0].findall('m:c', ns):
            v=c.find('m:v', ns)
            if v is None: headers.append(''); continue
            if c.attrib.get('t')=='s':
                headers.append(sst[int(v.text)])
            else:
                headers.append(v.text or '')
        print(f'{name}: {headers}')
        # check if any header looks like sku
        skuish=[h for h in headers if h and any(k in h.lower() for k in ('sku','id','code','barcode','upc'))]
