def test_wsgi_root_serves_product_home_and_try_serves_sandbox(tmp_path, monkeypatch):
    monkeypatch.setenv("SMOL_SESSIONS", str(tmp_path / "sessions"))
    monkeypatch.delenv("SMOL_SPONSOR_CALLS", raising=False)

    def start_response(status, headers):
        captured["status"] = status
        captured["headers"] = dict(headers)

    captured = {}
    home = b"".join(
        app(
            {
                "REQUEST_METHOD": "GET",
                "PATH_INFO": "/",
                "QUERY_STRING": "",
                "HTTP_HOST": "127.0.0.1",
                "wsgi.input": io.BytesIO(b""),
            },
            start_response,
        )
    ).decode()
    assert captured["status"].startswith("200")
    assert "Try the sandbox" in home
    assert "Practice runs" not in home

    captured.clear()
    sandbox = b"".join(
        app(
            {
                "REQUEST_METHOD": "GET",
                "PATH_INFO": "/try",
                "QUERY_STRING": "",
                "HTTP_HOST": "127.0.0.1",
                "wsgi.input": io.BytesIO(b""),
            },
            start_response,
        )
    ).decode()
    assert captured["status"].startswith("200")
    assert "Practice runs" in sandbox
    assert 'action="/try"' in sandbox


